   private RetCode CDLKICKINGBYLENGTH_OpenImpl( CDLKICKINGBYLENGTH_Stream sp, ReadOnlySpan<double> inOpen, ReadOnlySpan<double> inHigh, ReadOnlySpan<double> inLow, ReadOnlySpan<double> inClose, int startIdx )
